import json

# s42-s44 from D102 analysis
with open('artifacts/D102_null_s42_s44_fpr.json') as f:
    d42_44 = json.load(f)

# s45-s50 from fpr_transparency
with open('artifacts/fpr_transparency_all_seeds.json') as f:
    d45_50 = json.load(f)

# Count per-method FP for s42-s44
methods_s42_44 = {'diffxcorr': 0, 'permg': 0, 'threshold': 0, 'ty': 0, 'naive': 0}
for seed_data in d42_44['seeds']:
    for p in seed_data['pairs']:
        if p.get('diff_xcorr_fwd_sig_fdr', False):
            methods_s42_44['diffxcorr'] += 1
        if p.get('perm_granger_fwd_sig_fdr', False):
            methods_s42_44['permg'] += 1
        if p.get('threshold_onset_sig', False) and p.get('threshold_onset_lead') is not None and p['threshold_onset_lead'] > 0:
            methods_s42_44['threshold'] += 1
        if p.get('ty_granger_sig', False):
            methods_s42_44['ty'] += 1
        # Naive: sig AND peak_lag < 0 (forward)
        if p.get('naive_xcorr_sig', False) and p.get('naive_xcorr_lag', 0) < 0:
            methods_s42_44['naive'] += 1

print('s42-s44 (18 pairs):')
for m, c in methods_s42_44.items():
    print(f'  {m}: {c}/18 = {c/18*100:.1f}%')

# Count per-method FP for s45-s50
methods_s45_50 = {'diffxcorr': 0, 'permg': 0, 'threshold': 0, 'ty': 0, 'naive': 0}
for seed_data in d45_50.get('seeds', []):
    if isinstance(seed_data, dict) and 'pairs' in seed_data:
        for p in seed_data['pairs']:
            if p.get('diff_xcorr_fwd_sig_fdr', False):
                methods_s45_50['diffxcorr'] += 1
            if p.get('perm_granger_fwd_sig_fdr', False):
                methods_s45_50['permg'] += 1
            if p.get('threshold_onset_sig', False) and p.get('threshold_onset_lead') is not None and p['threshold_onset_lead'] > 0:
                methods_s45_50['threshold'] += 1
            if p.get('ty_granger_sig', False):
                methods_s45_50['ty'] += 1
            if p.get('naive_xcorr_sig', False) and p.get('naive_xcorr_lag', 0) < 0:
                methods_s45_50['naive'] += 1

print()
print('s45-s50 (36 pairs):')
for m, c in methods_s45_50.items():
    print(f'  {m}: {c}/36 = {c/36*100:.1f}%')

# Combined 9-seed
print()
print('Combined 9 seeds (54 pairs):')
for m in methods_s42_44:
    total = methods_s42_44[m] + methods_s45_50[m]
    print(f'  {m}: {total}/54 = {total/54*100:.1f}%')

# FPR range
all_rates = [(methods_s42_44[m] + methods_s45_50[m])/54*100 for m in methods_s42_44]
print(f'  Range: {min(all_rates):.1f}% to {max(all_rates):.1f}%')
